#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Level;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Level;
using UnityEngine;

namespace MVZ2.GameContent.Projectiles
{
    [EntityBehaviourDefinition(VanillaProjectileNames.iceBall)]
    public class IceBall : ProjectileBehaviour
    {
        public IceBall(string nsp, string name) : base(nsp, name)
        {
        }
        protected override void PostHitEntity(ProjectileHitOutput hitResult, DamageOutput? damageOutput)
        {
            base.PostHitEntity(hitResult, damageOutput);
            if (damageOutput == null)
                return;
            var entity = hitResult.Projectile;
            var other = hitResult.Other;

            if (!IsSplited(entity) && !hitResult.Pierce)
            {
                for (int i = 0; i < 2; i++)
                {
                    var direction = Quaternion.Euler(0, 45 - i * 90, 0) * entity.Velocity.normalized;
                    var velocity = direction * entity.Velocity.magnitude;
                    var projectile = other.ShootProjectile(new ShootParams()
                    {
                        projectileID = VanillaProjectileID.iceBall,
                        position = entity.Position,
                        velocity = velocity,
                        faction = entity.GetFaction(),
                        damage = entity.GetDamage() / 2
                    });
                    if (projectile != null)
                    {
                        projectile.SetScale(Vector3.one * 0.5f);
                        projectile.SetDisplayScale(Vector3.one * 0.5f);
                        projectile.SetShadowScale(Vector3.one * 0.5f);
                        SetSplited(projectile, true);
                    }
                }
            }
        }
        public static void SetSplited(Entity entity, bool value)
        {
            entity.SetBehaviourField(PROP_SPLIT, value);
        }

        public static bool IsSplited(Entity entity)
        {
            return entity.GetBehaviourField<bool>(PROP_SPLIT);
        }
        public static readonly VanillaEntityPropertyMeta<bool> PROP_SPLIT = new VanillaEntityPropertyMeta<bool>("Split");
    }
}
